// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    BANK_SAFE c;
    function setUp() public {
        c = new BANK_SAFE();
        c.SetMinSum(0);
        c.SetLogFile(address(new HelperLog()));
        c.Initialized();
    }

    function testFuzz_property(uint256 depositAmt, uint256 collectAmt) public {
        vm.assume(depositAmt > 0);
        vm.assume(collectAmt <= depositAmt);

        address actor = address(0x4242);
        vm.deal(actor, depositAmt);

        vm.prank(actor);
        c.Deposit{value: depositAmt}();

        uint256 balBefore = c.balances(actor);

        vm.prank(actor);
        c.Collect(collectAmt);

        assertEq(c.balances(actor), balBefore - collectAmt);
    }
}

contract HelperLog {
    function AddMessage(address, uint, string memory) external {}
}
